// function chunk(arr, size) mein array aur chunk size do
// Agar array nahi: []
// Agar size <= 0: []
// Warna chunks mein divide karo

solution:
function chunk(arr, size) {
  if (!Array.isArray(arr)) return []
  if (size <= 0) return []
  const chunks = []
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size))
  }
  return chunks
}
